{"format":"org.dxos.dx-svg@1","version":1,"root":"0000000000000DR50Z0WVND2CX","source":{"language":"dsl","text":"diagram flow=down
group local "Local host" {
  node Consumer "Consumer plugin"
  node Resolver "Service resolver" ref="packages/core/compute/compute/src/ServiceResolver.ts"
  node LocalProvider "Local provider"
  node Stub "Remote stub"
}
group shared "Shared by every host" {
  node Contract "Service contract"
  node Catalog "Service catalog" ref="packages/core/protocols/src/PluginProtocol.ts"
}
group remote "Remote host" {
  node Server "Service server" ref="packages/core/compute/plugin-host-cloudflare/src/PluginHost.ts"
  node RemoteProvider "Remote provider"
  node Features "Host features"
}
edge Consumer -> Resolver "get(contract)"
edge Resolver -> LocalProvider "in-memory call"
edge Resolver -> Stub "no local provider"
edge Stub -> Server "RPC"
edge Server -> RemoteProvider "calls handler"
edge RemoteProvider depends-on Features "needs"
edge LocalProvider implements Contract
edge RemoteProvider implements Contract
edge Resolver depends-on Catalog "who provides?"
edge Server -> Catalog "advertises"
"},"objects":[
